"use strict";(self.webpackChunkarkreen_docs=self.webpackChunkarkreen_docs||[]).push([[8581],{5610:e=>{e.exports=JSON.parse('{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"gettingStartedBar":[{"type":"category","label":"Arkreen in Brief","collapsed":false,"items":[{"type":"link","label":"What is Arkreen","href":"/","docId":"README"},{"type":"link","label":"Vision and Mission","href":"/getting-started/vision-mission","docId":"getting-started/vision-mission"},{"type":"link","label":"Participate in Arkreen","href":"/getting-started/participate","docId":"getting-started/participate"}],"collapsible":true},{"type":"category","label":"Community Programs","collapsed":true,"items":[{"type":"link","label":"Community Solar Program","href":"/programs/community-solar-program","docId":"programs/community-solar-program"},{"type":"link","label":"CSP Payment Safeguard Plan","href":"/programs/csp-payment-safeguard-plan","docId":"programs/csp-payment-safeguard-plan"},{"type":"link","label":"Referral Program","href":"/programs/referral-program","docId":"programs/referral-program"},{"type":"link","label":"Plug for Green Program","href":"/programs/plug-for-green-program","docId":"programs/plug-for-green-program"}],"collapsible":true,"href":"/programs/"},{"type":"category","label":"Quick Start","collapsed":true,"items":[{"type":"category","label":"Arkreen Newcomer Guide","collapsed":true,"items":[{"type":"link","label":"Claim Referral Gift","href":"/quick-start/arkreen-newcomer-guide/claim-referral-gift","docId":"quick-start/arkreen-newcomer-guide/claim-referral-gift"}],"collapsible":true,"href":"/quick-start/arkreen-newcomer-guide/"},{"type":"link","label":"Arkreen Simple Staking Guide","href":"/quick-start/staking-guide","docId":"quick-start/staking-guide"},{"type":"link","label":"Arkreen Smart Plug Quick Start","href":"/quick-start/smart-plug-quick-start","docId":"quick-start/smart-plug-quick-start"}],"collapsible":true}],"overviewBar":[{"type":"category","label":"Arkreen Narrative","collapsed":true,"items":[{"type":"link","label":"Why, What and How","href":"/overview/wwh/why-what-how","docId":"overview/wwh/why-what-how"},{"type":"link","label":"Tactical Approach","href":"/overview/wwh/tactical-approach","docId":"overview/wwh/tactical-approach"},{"type":"link","label":"Implementing the Solution","href":"/overview/wwh/implementing-solution","docId":"overview/wwh/implementing-solution"}],"collapsible":true},{"type":"category","label":"DePIN Model","collapsed":true,"items":[{"type":"link","label":"Supply Side","href":"/overview/depinmodel/supply-side","docId":"overview/depinmodel/supply-side"},{"type":"link","label":"Demand Side","href":"/overview/depinmodel/demand-side","docId":"overview/depinmodel/demand-side"},{"type":"link","label":"Token Model","href":"/overview/depinmodel/token-model","docId":"overview/depinmodel/token-model"}],"collapsible":true,"href":"/overview/depinmodel/"},{"type":"category","label":"Market and Product Stack","collapsed":true,"items":[{"type":"link","label":"Go-to-Market Strategy","href":"/overview/market-product/go-to-market","docId":"overview/market-product/go-to-market"},{"type":"link","label":"Core Product Stack","href":"/overview/market-product/core-product-stack","docId":"overview/market-product/core-product-stack"}],"collapsible":true},{"type":"category","label":"Arkreen Miners","collapsed":true,"items":[{"type":"category","label":"Energy Generation Category","collapsed":false,"items":[{"type":"link","label":"Remote Miner","href":"/overview/miner/generation/remote-miner","docId":"overview/miner/generation/remote-miner"},{"type":"link","label":"Remote Miner Pro","href":"/overview/miner/generation/remote-miner-pro","docId":"overview/miner/generation/remote-miner-pro"},{"type":"link","label":"Lite Remote Miner","href":"/overview/miner/generation/lite-remote-miner","docId":"overview/miner/generation/lite-remote-miner"},{"type":"link","label":"Plant Miner","href":"/overview/miner/generation/plant-miner","docId":"overview/miner/generation/plant-miner"},{"type":"link","label":"Standard Miner","href":"/overview/miner/generation/standard-miner","docId":"overview/miner/generation/standard-miner"},{"type":"link","label":"Obsoleted: Gaming Miner","href":"/overview/miner/generation/gaming-miner","docId":"overview/miner/generation/gaming-miner"}],"collapsible":true},{"type":"category","label":"Energy Consumption Category","collapsed":false,"items":[{"type":"link","label":"Consumption Plug Miner","href":"/overview/miner/consumption/plug-miner","docId":"overview/miner/consumption/plug-miner"}],"collapsible":true}],"collapsible":true,"href":"/overview/miner/"}],"roadmapBar":[{"type":"link","label":"Roadmap Overview","href":"/roadmap/roadmap-overview","docId":"roadmap/roadmap-overview"},{"type":"link","label":"Phase 0","href":"/roadmap/phase0","docId":"roadmap/phase0"},{"type":"link","label":"Phase 1","href":"/roadmap/phase1","docId":"roadmap/phase1"},{"type":"link","label":"Phase 2","href":"/roadmap/phase2","docId":"roadmap/phase2"},{"type":"link","label":"Phase 3","href":"/roadmap/phase3","docId":"roadmap/phase3"}],"economyBar":[{"type":"category","label":"Token","collapsed":false,"items":[{"type":"link","label":"What is AKRE?","href":"/token/what-is-akre","docId":"token/what-is-akre"},{"type":"link","label":"Network Primitives","href":"/token/network-primitives","docId":"token/network-primitives"},{"type":"link","label":"Token Distribution","href":"/token/token-distribution","docId":"token/token-distribution"},{"type":"link","label":"Utility Token","href":"/token/utility-token","docId":"token/utility-token"},{"type":"link","label":"Token Burn","href":"/token/token-burn","docId":"token/token-burn"}],"collapsible":true},{"type":"category","label":"Economic Model","collapsed":false,"items":[{"type":"link","label":"Economic Model Overview","href":"/ecomodel/ecomodel_overview","docId":"ecomodel/ecomodel_overview"}],"collapsible":true}],"arecBar":[{"type":"category","label":"AREC","collapsed":true,"items":[{"type":"link","label":"AREC Overview","href":"/arec/arec-overview","docId":"arec/arec-overview"},{"type":"link","label":"Climate Actors","href":"/arec/climate-actors","docId":"arec/climate-actors"},{"type":"link","label":"AREC Assets","href":"/arec/arec-assets","docId":"arec/arec-assets"},{"type":"link","label":"ART Token","href":"/arec/art-token","docId":"arec/art-token"},{"type":"link","label":"Climate Badge","href":"/arec/climate-badge","docId":"arec/climate-badge"},{"type":"category","label":"AREC DApp","collapsed":true,"items":[{"type":"link","label":"AREC Quick Start","href":"/arec/arec-quickstart","docId":"arec/arec-quickstart"},{"type":"link","label":"AREC Profile","href":"/arec/arec-profile","docId":"arec/arec-profile"},{"type":"link","label":"Issue AREC","href":"/arec/issue-arec","docId":"arec/issue-arec"},{"type":"link","label":"Redeem AREC","href":"/arec/redeem-arec","docId":"arec/redeem-arec"},{"type":"link","label":"Liquidize AREC","href":"/arec/liquidize-arec","docId":"arec/liquidize-arec"},{"type":"link","label":"Offset ART","href":"/arec/offset-art","docId":"arec/offset-art"},{"type":"link","label":"AREC Badge","href":"/arec/arec-badge","docId":"arec/arec-badge"},{"type":"link","label":"Arkreen DEX","href":"/arec/arec-dex","docId":"arec/arec-dex"}],"collapsible":true,"href":"/arec/arec-dapp"},{"type":"link","label":"AREC Bridge","href":"/arec/arec-bridge","docId":"arec/arec-bridge"},{"type":"link","label":"AREC Port","href":"/arec/arec-port","docId":"arec/arec-port"}],"collapsible":true},{"type":"link","label":"REC RWA","href":"/arec/rec-rwa","docId":"arec/rec-rwa"}],"moreBar":[{"type":"category","label":"How to Use","collapsed":true,"items":[{"type":"link","label":"Arkreen Console","href":"/how-to-use/arkreen-console","docId":"how-to-use/arkreen-console"},{"type":"link","label":"Arkreen Explorer","href":"/how-to-use/arkreen-explorer","docId":"how-to-use/arkreen-explorer"},{"type":"link","label":"Arkreen App","href":"/how-to-use/arkreen-app","docId":"how-to-use/arkreen-app"},{"type":"link","label":"Data Collector Installation","href":"/how-to-use/data-collector-installation","docId":"how-to-use/data-collector-installation"},{"type":"link","label":"Arkreen Smart Plug","href":"/how-to-use/smart-plug-user-guide","docId":"how-to-use/smart-plug-user-guide"}],"collapsible":true},{"type":"category","label":"Technical Details","collapsed":true,"items":[{"type":"category","label":"Proof of Green Data","collapsed":true,"items":[{"type":"link","label":"How does a Miner fulfill the Proof of Green Data task?","href":"/technical-details/proof-of-green-data/how-does-a-miner-fulfill-the-proof-of-green-data-task","docId":"technical-details/proof-of-green-data/how-does-a-miner-fulfill-the-proof-of-green-data-task"},{"type":"link","label":"How does Arkreen Network determine which Miner will be rewarded?","href":"/technical-details/proof-of-green-data/how-does-arkreen-network-determine-which-Miner-will-be-rewarded","docId":"technical-details/proof-of-green-data/how-does-arkreen-network-determine-which-Miner-will-be-rewarded"},{"type":"link","label":"How does Arkreen Network verify the trustworthiness of Proof of Green Data?","href":"/technical-details/proof-of-green-data/how-does-arkreen-network-verify-the-trustworthiness-of-proof-of-green-data","docId":"technical-details/proof-of-green-data/how-does-arkreen-network-verify-the-trustworthiness-of-proof-of-green-data"},{"type":"link","label":"How does Arkreen Network calculate the token amount that a Miner will earn?","href":"/technical-details/proof-of-green-data/how-does-arkreen-network-calculate-the-token-amount-that-a-miner-will-earn","docId":"technical-details/proof-of-green-data/how-does-arkreen-network-calculate-the-token-amount-that-a-miner-will-earn"}],"collapsible":true,"href":"/technical-details/proof-of-green-data/overview"},{"type":"link","label":"How does Plant Miner get rewards","href":"/technical-details/plant-miner-rewards","docId":"technical-details/plant-miner-rewards"},{"type":"link","label":"Electricity-generation data Storage in Filecoin","href":"/technical-details/electricity-generation-data-storage-in-filecoin","docId":"technical-details/electricity-generation-data-storage-in-filecoin"},{"type":"link","label":"Smart contract deployment","href":"/technical-details/smart-contract-deployment","docId":"technical-details/smart-contract-deployment"}],"collapsible":true},{"type":"category","label":"FAQ","collapsed":true,"items":[{"type":"link","label":"Buy Remote Miner","href":"/faq/buy-remote-miner","docId":"faq/buy-remote-miner"},{"type":"link","label":"Reward and Withdrawal","href":"/faq/reward-and-withdrawal","docId":"faq/reward-and-withdrawal"},{"type":"link","label":"Energy and Miner Status","href":"/faq/energy-and-miner-status","docId":"faq/energy-and-miner-status"},{"type":"link","label":"\\"Road to DePIN+ReFi\\" Campaign","href":"/faq/road-to-depin-refi-campaign","docId":"faq/road-to-depin-refi-campaign"},{"type":"link","label":"AREC FAQs","href":"/faq/arec-faq","docId":"faq/arec-faq"}],"collapsible":true},{"type":"category","label":"Archived","collapsed":true,"items":[{"type":"link","label":"Arkreen Mainnet Transition","href":"/quick-start/mainnet-transition","docId":"quick-start/mainnet-transition"}],"collapsible":true}]},"docs":{"arec/arec-assets":{"id":"arec/arec-assets","title":"Arkreen Ecosystem Assets","description":"In the Arkreen ecosystem, there are several kinds of digital assets:","sidebar":"arecBar"},"arec/arec-badge":{"id":"arec/arec-badge","title":"How to Mint Retirement Badge","description":"The climate actor may freely mint the carbon retirement badge based on the climate actions created by redeeming AREC NFTs or offsetting ART tokens. The climate action is only effective once to mint the climate badge. Some information, such as the retirement entity, retirement beneficiary, and retirement supplementary remarks can be recorded in the retirement badge. With this badge, you could demonstrate your contribution to protecting our Planet and make that verifiable for governmental agencies, administrative departments, or other 3rd parties.","sidebar":"arecBar"},"arec/arec-bridge":{"id":"arec/arec-bridge","title":"AREC Bridge","description":"In addition to issuing AREC based on renewable energy generation proof sourced from the Arkreen network, the AREC Dapp goes a step further by offering support for the issuance of AREC assets using classic REC assets like I-REC, TIGR, Green-e, and others. This unique capability, called as the AREC bridge feature, enables the seamless integration of traditional RECs from the physical world into the innovative Web3 ecosystem.","sidebar":"arecBar"},"arec/arec-dapp":{"id":"arec/arec-dapp","title":"AREC Dapp","description":"AREC DApp is the one-stop AREC service access entrypoint for the Arkreen community members to manage AREC related assets. It relies on multiple smart contracts deployed on the blockchain to provide services around AREC, including: issuing AREC, redeeming AREC,liquidizing AREC to ART, offsetting ART, solidifying ART to AREC, buying ART and minting Arkreen badge.","sidebar":"arecBar"},"arec/arec-dex":{"id":"arec/arec-dex","title":"arec-dex","description":"Arkreen DEX will come soon.","sidebar":"arecBar"},"arec/arec-overview":{"id":"arec/arec-overview","title":"AREC Overview","description":"AREC, Arkreen Renewable Energy Certificate, is the REC issued on the basis of the renewable energy generation proof sourcing from the Arkreen Network. With the help of high efficiency and amazing composability of the Web3 technology, AREC targets to be the fundamental financial instrument to gear up the global carbon emission reduction progress.","sidebar":"arecBar"},"arec/arec-port":{"id":"arec/arec-port","title":"AREC Port","description":"The standard process of utilizing AREC (Arkreen Renewable Energy Certificate) to offset one\'s energy consumption is as follows: purchase and redeem AREC NFTs to commit climate actions, or buy and offset ART tokens to commit climate actions. Then, based on the climate action(s), mint a climate badge, which may serve as proof of carbon neutrality for the badge beneficiary.","sidebar":"arecBar"},"arec/arec-profile":{"id":"arec/arec-profile","title":"AREC Asset Profile","description":"This is the first page while you visit the AREC Dapp. Two level of AREC assets are displayed in two separate sub-pages:","sidebar":"arecBar"},"arec/arec-quickstart":{"id":"arec/arec-quickstart","title":"AREC Quick Start","description":"Follow these steps to seamlessly mint ART tokens from green energy generation.","sidebar":"arecBar"},"arec/art-token":{"id":"arec/art-token","title":"ART Token","description":"ART tokens are minted while an AREC NFT is liquidized by the user. Liquidization is the process in which the user transfers the owned AREC NFT to the ART smart contract, the AREC NFT is set to Liquidized state, and the exact same amount of ART tokens as the amount of the RE output in the liquidized AREC NFT are minted to the user\'s account.","sidebar":"arecBar"},"arec/climate-actors":{"id":"arec/climate-actors","title":"AREC Climate Actors","description":"There are two breeds of distinguished climate actors within the Arkreen ecosystem: renewable energy generators and climate actors.","sidebar":"arecBar"},"arec/climate-badge":{"id":"arec/climate-badge","title":"Climate Badge","description":"The Climate badge is minted based on one or more climate actions created during the process of redeeming AREC NFTs or offsetting ART tokens. Each climate badge contains comprehensive retirement information. With this data, it becomes possible to trace back and identify all the original AREC NFTs that were retired to create the badge. This detailed record-keeping feature ensures transparency and accountability for the climate actions associated with the badge.","sidebar":"arecBar"},"arec/issue-arec":{"id":"arec/issue-arec","title":"How to issue an AREC","description":"Go to AREC Issuance.","sidebar":"arecBar"},"arec/liquidize-arec":{"id":"arec/liquidize-arec","title":"How to Liquidize an AREC NFT","description":"Liquidizing an AREC NFT means setting the AREC NFT to the Liquidized state, and minting some amount of ART, the Arkreen Renewable-Energy Token, to the owner\'s wallet. The newly minted amount of ART is exactly the same as the amount of the RE conveyed by the liquidized AREC.","sidebar":"arecBar"},"arec/offset-art":{"id":"arec/offset-art","title":"How to Offset ART","description":"Offsetting ART means burning your ART tokens to create a climate action. Climate action is a record in the blockchain, which stores all the carbon offset relative information, such as owner of the action, RE amount in the action, AREC NFT ID linked to this action, etc.","sidebar":"arecBar"},"arec/rec-rwa":{"id":"arec/rec-rwa","title":"Renewable Energy Certificate Real-World Asset (REC RWA) Trial","description":"|BUY REC RWA|","sidebar":"arecBar"},"arec/redeem-arec":{"id":"arec/redeem-arec","title":"How to redeem the AREC","description":"Redeeming AREC means setting the AREC NFT into the Retired state. The lifecycle of the AREC NFT is thus Retired, and permanently terminated from usage ever again","sidebar":"arecBar"},"ecomodel/ecomodel_overview":{"id":"ecomodel/ecomodel_overview","title":"Economic Model","description":"As a Web3-enabled data network for distributed renewable energy resources (DERs), the essential economic model of Arkreen is a commission fee based model.","sidebar":"economyBar"},"faq/arec-faq":{"id":"faq/arec-faq","title":"AREC FAQs","description":"Q1: I tried AREC Quick Start in 2 browsers (or 2 computers/cellphones). The 2 browsers show inconsistent information or get stuck when issuing ART. How can I deal with it?","sidebar":"moreBar"},"faq/buy-remote-miner":{"id":"faq/buy-remote-miner","title":"Buy Remote Miner","description":"Q1: What is the difference between a Remote Miner and a Standard Miner?","sidebar":"moreBar"},"faq/energy-and-miner-status":{"id":"faq/energy-and-miner-status","title":"Energy and Miner Status","description":"Q1: I just purchased a Remote Miner. Why does it report zero power in the past a few hours?","sidebar":"moreBar"},"faq/order-standard-miner":{"id":"faq/order-standard-miner","title":"Order A Standard Miner","description":"Q1: How can I order a Standard Miner?"},"faq/reward-and-withdrawal":{"id":"faq/reward-and-withdrawal","title":"Reward and Withdrawal","description":"Q1: I see reward in the dashboard, but why does my Metamask display no reward token at all?","sidebar":"moreBar"},"faq/road-to-depin-refi-campaign":{"id":"faq/road-to-depin-refi-campaign","title":"\\"Road to DePIN+ReFi\\" Campaign","description":"Q1: What is \\"Road to DePIN+ReFi\\" Campaign?","sidebar":"moreBar"},"getting-started/participate":{"id":"getting-started/participate","title":"Participate in Arkreen","description":"There are various ways to participate in Arkreen and earn the AKRE utility token, either on the Supply Side or the Demand Side.","sidebar":"gettingStartedBar"},"getting-started/vision-mission":{"id":"getting-started/vision-mission","title":"Vision and Mission","description":"Arkreen is dedicated to promoting inclusive climate action on a global scale through a community-driven, bottom-up approach. By building a trusted digital foundation for renewable energy and creating a public network for green assets, Arkreen invites global community builders to join in constructing a sustainable future.","sidebar":"gettingStartedBar"},"governance/arkreen-mariners":{"id":"governance/arkreen-mariners","title":"Arkreen Mariners","description":"Based on the principles of decentralization, efficiency and security, the Arkreen Network construction team will include a core team and a community team. The core team will be responsible for the construction of the core functions of the Arkreen network and the early establishment and operation of the foundation. The community team will be responsible for network technology, applications, cooperation, community, media and other tasks. The network construction principles include : how the funded team will assume corresponding responsibilities; how the construction content and sponsorship usage details are disclosed in a completely transparent manner; how the construction team is supervised by the foundation and the community; how network construction adopts a token-based governance decision-making model."},"governance/community-owned":{"id":"governance/community-owned","title":"Community Owned","description":"Arkreen will adopt a DAO (foundation) governance model"},"governance/governance-overview":{"id":"governance/governance-overview","title":"Governance Overview","description":"As a DAO (decentralized autonomous organization) based on the intersection of clean energy (public attributes) and our evolving digital economy, Arkreen\'s governance model and economic model refer to a country\'s historical experience and lavishly draws on the wisdom of our predecessors."},"governance/voting":{"id":"governance/voting","title":"Voting","description":"During early stages, voting will be for (1) selecting accredited governance committee member to participate in network governance; (2) voting on matters that AIP cannot work. After the network has matured (expected in 3-5 years), we will transition to a pure on-chain voting model in stages. The specific vote will be for (1)(2) as mentioned above, and (3) to initiate, support or modify a proposal under the premise that the approval rate reaches 1%."},"how-to-use/arkreen-app":{"id":"how-to-use/arkreen-app","title":"Arkreen App","description":"TBD","sidebar":"moreBar"},"how-to-use/arkreen-console":{"id":"how-to-use/arkreen-console","title":"Arkreen Console","description":"Arkreen Console","sidebar":"moreBar"},"how-to-use/arkreen-explorer":{"id":"how-to-use/arkreen-explorer","title":"Arkreen Explorer","description":"Arkreen Explorer","sidebar":"moreBar"},"how-to-use/data-collector-installation":{"id":"how-to-use/data-collector-installation","title":"Data Collector Installation","description":"If you are interested in connecting your existing solar PV system to Arkreen Network, please fill in the form below:","sidebar":"moreBar"},"how-to-use/green-btc":{"id":"how-to-use/green-btc","title":"Green BTC Club","description":"Bitcoin mining plays a crucial role in maintaining the security and integrity of the Bitcoin network. It also consumes a significant amount of energy, and much of that energy comes from non-renewable sources like coal and natural gas. According to the Cambridge Bitcoin Electricity Consumption Index, Bitcoin\'s estimated annual electricity consumption in the year of 2022 is around 107 TWh (terawatt hours), which is more than the entire energy consumption of some countries."},"how-to-use/smart-plug-user-guide":{"id":"how-to-use/smart-plug-user-guide","title":"User Guide for Arkreen Smart Plug","description":"How to Participate?","sidebar":"moreBar"},"nft/miner-nft":{"id":"nft/miner-nft","title":"Miner NFT","description":"An NFT will be minted for every miner."},"overview/depinmodel/demand-side":{"id":"overview/depinmodel/demand-side","title":"Demand-Side Mechanisms: Play to Impact","description":"On the demand side, individuals can achieve voluntary carbon neutrality by purchasing tokenized green assets on DEXs. These green assets could either originate from Arkreen\u2019s supply-side activities or be tokenized external carbon assets bridged into the network. By offsetting their carbon footprint on-chain, users contribute to voluntary carbon neutrality. Arkreen rewards these actions with utility tokens (AKRE).","sidebar":"overviewBar"},"overview/depinmodel/README":{"id":"overview/depinmodel/README","title":"Supply-Side Mechanisms, Demand-Side Mechanisms, and Token Model","description":"Arkreen leverages the community-driven DePIN model and token incentives to initiate both the supply and demand sides of its network.","sidebar":"overviewBar"},"overview/depinmodel/supply-side":{"id":"overview/depinmodel/supply-side","title":"Supply-Side Mechanisms: Impact to Earn","description":"On the supply side, Arkreen focuses on digitizing individual green behaviors using IoT solutions. These behaviors include activities such as generating solar power from rooftop installations, optimizing home air conditioning for energy efficiency, or using electric vehicles. Once digitized, these actions are structured according to specific methodologies and registered on the blockchain as green assets.","sidebar":"overviewBar"},"overview/depinmodel/token-model":{"id":"overview/depinmodel/token-model","title":"Token Model: Utility for Value Capture and Incentive Reward","description":"The utility token AKRE is crucial to Arkreen\u2019s ecosystem. It pays transaction fees for issuing, offsetting, and trading green assets. This token model captures external value and supports the inclusive climate action platform and public green asset network.","sidebar":"overviewBar"},"overview/market-product/core-product-stack":{"id":"overview/market-product/core-product-stack","title":"Core Product Stacks: Advancing Decentralized and Inclusive Climate Solutions","description":"Arkreen\u2019s network includes three core product stacks:","sidebar":"overviewBar"},"overview/market-product/go-to-market":{"id":"overview/market-product/go-to-market","title":"Go-to-Market Strategy: Expanding DePIN and ReFi Ecosystems","description":"Arkreen\u2019s short to medium-term market strategy involves actively expanding DePIN projects within the Web3 market. These projects will register their green activities and Proof of Physical Work (PoPW) with Arkreen to issue green assets and monetize their efforts. Additionally, Arkreen plans to collaborate with ReFi projects or Web3 initiatives that have ESG goals, aligning their on-chain voluntary carbon offset needs with Arkreen\u2019s green asset consumption. For the traditional market, green asset sellers can use Arkreen to issue their assets for better returns without intermediary overheads, while buyers can benefit from 24/7 trading and access to high-transparency, impactful green assets, such as renewable energy projects in Africa.","sidebar":"overviewBar"},"overview/miner/consumption/plug-miner":{"id":"overview/miner/consumption/plug-miner","title":"Consumption Plug Miner","description":"In addition to Energy Generation Category, a new Energy Consumption Category is introduced, which includes a new formfactor Consumption Plug Miner as one of its components. A smart plug can calculate how much energy an electrical appliance consumes as well as schedule the power supply remotely. The users could power up their appliances (e.g. air conditioner) by the smart plug to participate in the green actions.","sidebar":"overviewBar"},"overview/miner/generation/gaming-miner":{"id":"overview/miner/generation/gaming-miner","title":"Obsoleted: Gaming Miner","description":"Gaming Miner is NOT applicable since Phase 1. The information is for archive only.","sidebar":"overviewBar"},"overview/miner/generation/lite-remote-miner":{"id":"overview/miner/generation/lite-remote-miner","title":"Lite Remote Miner","description":"A Lite Remote Miner is a special type of Remote Miner, which is for airdropping purpose. Lite Remote Miner has different rated capacity and lifespan from the conventional Remote Miner. The default capacity and lifespan are 5 Watt for 3 months.","sidebar":"overviewBar"},"overview/miner/generation/plant-miner":{"id":"overview/miner/generation/plant-miner","title":"Plant Miner","description":"A Plant Miner is a collection of energy data from a physical green energy generation facility, to feed Remote Miners. The energy facility is connected to an IoT device that collects energy generation data. The collected data is fractionized to feed several Remote Miners as if these Remote Miners were generating the energy.","sidebar":"overviewBar"},"overview/miner/generation/remote-miner":{"id":"overview/miner/generation/remote-miner","title":"Remote Miner","description":"A Remote Miner is a fractional miner running remotely and earn AKRE rewards. Every Remote Miner binds to an green energy generation facility (e.g. solar photovoltaic plant). The energy facility is connected to an IoT device that collects energy generation data. The collected data is fractionized to feed several Remote Miners as if these Remote Miners were generating the energy. Unless explicitly stated, Remote Miner\'s default capacity is 100 Watt (0.1kW) and its default lifespan is 1-year subscription since it\'s purchased.","sidebar":"overviewBar"},"overview/miner/generation/remote-miner-pro":{"id":"overview/miner/generation/remote-miner-pro","title":"Remote Miner Pro (Trial)","description":"|BUY Remote Miner Pro|","sidebar":"overviewBar"},"overview/miner/generation/standard-miner":{"id":"overview/miner/generation/standard-miner","title":"Standard Miner","description":"A Standard Miner is a collection of energy data from a physical green energy generation facility. It\'s similar to a Plant Miner. Both of them acquire green energy data from physical energy facilities. The difference is, a Standard Miner gets AKRE rewards directly on the basis of how much energy it generates, with a normalization method that regularizes the reward weight. Note that the normalization method leads to a non-linear reward curve that higher power above a threshold contributes to less rewards. A Standard Miner NFT will be minted per each Standard Miner upon miner on-boarding.","sidebar":"overviewBar"},"overview/miner/README":{"id":"overview/miner/README","title":"Arkreen Miner","description":"Energy Generation Category","sidebar":"overviewBar"},"overview/pillar-applications":{"id":"overview/pillar-applications","title":"Pillar Applications","description":"Generation of Renewable Energy Certificates"},"overview/wwh/implementing-solution":{"id":"overview/wwh/implementing-solution","title":"Implementing the Solution: Technology and Community-Driven Strategies","description":"Arkreen utilizes blockchain and tokenization technologies to support the full lifecycle of green assets \u2014 from digital certification and registration to trading and consumption. This ReFi (Regenerative Finance) model aligns financial incentives with environmental benefits.","sidebar":"overviewBar"},"overview/wwh/tactical-approach":{"id":"overview/wwh/tactical-approach","title":"Tactical Approach: Targeting Individual Contributions to Carbon Neutrality","description":"While the scope of carbon assets is vast, Arkreen focuses on making the system accessible and beneficial for individuals. Current carbon markets predominantly cater to corporations, leaving individuals who want to contribute to climate action without practical tools or recognition.","sidebar":"overviewBar"},"overview/wwh/why-what-how":{"id":"overview/wwh/why-what-how","title":"Arkreen\'s Why, What and How","description":"Why We Need a Decentralized Carbon Asset Network","sidebar":"overviewBar"},"programs/affiliate-program":{"id":"programs/affiliate-program","title":"Affiliate Program","description":"Apply Now//forms.gle/ooWnC4zTU8pdPiy79"},"programs/community-solar-program":{"id":"programs/community-solar-program","title":"Community Solar Program","description":"Objective","sidebar":"gettingStartedBar"},"programs/csp-payment-safeguard-plan":{"id":"programs/csp-payment-safeguard-plan","title":"CSP Payment Safeguard Plan: Immediate Rewards Guaranteed for Enhanced User Experience!","description":"Thank you for choosing CSP products and becoming part of the Arkreen family. We understand the urgency to swiftly participate in climate action and achieve \'impact to earn\' after payment. Additionally, we are committed to minimizing any potential logistic delays during the initial launch of CSP hardware sales in new countries or regions not included in the trial phase.","sidebar":"gettingStartedBar"},"programs/plug-for-green-program":{"id":"programs/plug-for-green-program","title":"Plug for Green Program","description":"What is Plug for Green Program","sidebar":"gettingStartedBar"},"programs/README":{"id":"programs/README","title":"Arkreen Community Programs","description":"Arkreen Community Programs are special programs that encourage people to participate in and co-build the network.","sidebar":"gettingStartedBar"},"programs/referral-program":{"id":"programs/referral-program","title":"A User Guide to  Arkreen Referral Program: Crafting Your Arkreen Referral Link for Rewards","description":"Background","sidebar":"gettingStartedBar"},"quick-start/arkreen-newcomer-guide/claim-referral-gift":{"id":"quick-start/arkreen-newcomer-guide/claim-referral-gift","title":"Claim Referral Gift - Lite Remote Miners Free Gift","description":"For each remote miner being purchased by your friend through your referral link, you can claim a Lite Remote Miner as a gift. Take action now and build your exclusive Arkreen network!","sidebar":"gettingStartedBar"},"quick-start/arkreen-newcomer-guide/README":{"id":"quick-start/arkreen-newcomer-guide/README","title":"Arkreen Newcomer Guide","description":"Welcome to Arkreen ecosystem! We will quickly guide you through your first time on the dashboard.","sidebar":"gettingStartedBar"},"quick-start/mainnet-transition":{"id":"quick-start/mainnet-transition","title":"Arkreen Mainnet Transition","description":"We\'re excited to announce the launch of Arkreen Mainnet, featuring an airdrop, a tAKRE to AKRE conversion plan, token holder governance, and an on-chain Arkreen Miners migration strategy.","sidebar":"moreBar"},"quick-start/smart-plug-quick-start":{"id":"quick-start/smart-plug-quick-start","title":"Arkreen Smart Plug Quick Start","description":"Note: Smart Plug is under white-list test.","sidebar":"gettingStartedBar"},"quick-start/staking-guide":{"id":"quick-start/staking-guide","title":"Arkreen Simple Staking Guide","description":"1. Withdrawing AKRE","sidebar":"gettingStartedBar"},"README":{"id":"README","title":"What is Arkreen","description":"Arkreen is the combination of Ark and (g)reen, meaning an ark aggregating and carrying green energy data to the future.","sidebar":"gettingStartedBar"},"roadmap/phase0":{"id":"roadmap/phase0","title":"Phase 0","description":"Phase 0 is the first phase for the development and user early experience purposes.","sidebar":"roadmapBar"},"roadmap/phase1":{"id":"roadmap/phase1","title":"Phase 1","description":"The Phase 1 period commences the first applicable phase of Arkreen Network which is fed with real energy data, to support the uplink data aggregation.","sidebar":"roadmapBar"},"roadmap/phase2":{"id":"roadmap/phase2","title":"Phase 2","description":"The Phase 2 period represents an expanded stage for the Arkreen Network mainnet to support bi-directional data/control aggregation for more scenarios.","sidebar":"roadmapBar"},"roadmap/phase3":{"id":"roadmap/phase3","title":"Phase 3","description":"The Phase 3 period will allow for a thriving sub-DAO driven ecosystem to flourish for DERs and decarbonization. As more and more energy prosumers are connected, the Arkreen Network is anticipated to metamorphosize into a sub-DAO community. Participants in various sectors are self-organized to build up climate+crypto solutions. For Climate change advocates, a thriving Regenerative Finance (ReFi) ecosystem of players are expected to monetize energy network data and help Arkreen Network flourish.","sidebar":"roadmapBar"},"roadmap/roadmap-overview":{"id":"roadmap/roadmap-overview","title":"Roadmap Overview","description":"Arkreen Network is built by integrating IoT, AI, blockchain and token economy. Each of them is a big topic. In today\u2019s trivergent environment, the physical and digital worlds meshing together is a gamer changer that allows Arkreen Network to be built into a unique visionary product offering!","sidebar":"roadmapBar"},"technical-details/electricity-generation-data-storage-in-filecoin":{"id":"technical-details/electricity-generation-data-storage-in-filecoin","title":"Electricity-generation data Storage in Filecoin","description":"Many decentralized global infrastructure platforms, such as Arkreen Network, that combine crypto-economic incentives, blockchain, and the Internet of Things (IoT), convergent solutions together have a singular opportunity to promote collective action toward mitigating carbon emissions, demonstrate industry-wide decarbonization, and stimulate new demand for clean energy resources.  Arkreen is a web-3 decentralized global resource energy distribution platform built on the Polygon blockchain network and powered by Filecoin green storage to enable the interconnection and monetization of distributed energy resources for carbon reduction applications.","sidebar":"moreBar"},"technical-details/plant-miner-rewards":{"id":"technical-details/plant-miner-rewards","title":"How does Plant Miner get rewards?","description":"Unlike other miners in the Energy Generation Category, Plant Miner\'s rewards are not directly calculated from the energy it generates. Instead, the rewards a Plant Miner gets are proportional to the rewards the Remote Miners (fed by this Plant Miner) get. The reward pool for Plant Miner is separate from the other miners\'.","sidebar":"moreBar"},"technical-details/proof-of-green-data/how-does-a-miner-fulfill-the-proof-of-green-data-task":{"id":"technical-details/proof-of-green-data/how-does-a-miner-fulfill-the-proof-of-green-data-task","title":"How does a Miner fulfill the Proof of Green Data task?","description":"The Arkreen Network rewards Miners who consistently report high-quality green energy data. All Miners connected to the Arkreen Network need to sample data every 5 minutes and buffer it locally for 1 hour, and report all the buffered data every 1 hour. After the Miner reports this data, it can clear the local data buffer and prepare for the next data report. The green energy data that each miner will sample includes the following below:","sidebar":"moreBar"},"technical-details/proof-of-green-data/how-does-arkreen-network-calculate-the-token-amount-that-a-miner-will-earn":{"id":"technical-details/proof-of-green-data/how-does-arkreen-network-calculate-the-token-amount-that-a-miner-will-earn","title":"How does Arkreen Network calculate the token amount that a Miner will earn?","description":"Arkreen Network distributes the reward to the miners (except for Plant Miner) according to the trustworthiness of green energy generation data, the normalized quantity of data and the normalized volume of energy, the detailed calculation process is as follows.","sidebar":"moreBar"},"technical-details/proof-of-green-data/how-does-arkreen-network-determine-which-Miner-will-be-rewarded":{"id":"technical-details/proof-of-green-data/how-does-arkreen-network-determine-which-Miner-will-be-rewarded","title":"How does Arkreen Network determine which Miner will be rewarded?","description":"Every miner has a chance to earn the Proof of Green Data reward about every K epochs, where currently K=2. In the first block of every epoch, Arkreen Network will generate a key pair, and publish the public key (verifiable random number). In the first block of the next epoch, Arkreen Network will use the private key of the key pair to decide the miners that will be rewarded and publish the private key (verifiable evidence). The decision process flow is listed hereunder:","sidebar":"moreBar"},"technical-details/proof-of-green-data/how-does-arkreen-network-verify-the-trustworthiness-of-proof-of-green-data":{"id":"technical-details/proof-of-green-data/how-does-arkreen-network-verify-the-trustworthiness-of-proof-of-green-data","title":"How does Arkreen Network verify the trustworthiness of Proof of Green Data?","description":"In order to avoid miners reporting fake power generation data to the network, Arkreen Network uses a set of novel methods for data authenticity judgment. The exact method depends on the category of the miners.","sidebar":"moreBar"},"technical-details/proof-of-green-data/overview":{"id":"technical-details/proof-of-green-data/overview","title":"Proof of Green Data and Reward Distribution","description":"The Arkreen Network uses a set of novel algorithms called Proof of Green Data to monitor Arkreen Network\u2019s green energy generation, consumption and storage. All miners who correctly fulfill the Proof of Green Data tasks will be rewarded. The Proof of Green Data helps the Arkreen Network measure its generation, consumption and storage capacity, which is the basis for the network to provide green energy data asset related services.","sidebar":"moreBar"},"technical-details/smart-contract-deployment":{"id":"technical-details/smart-contract-deployment","title":"Smart Contract Deployment","description":"Arkreen ecosystem includes several renewable energy certificate supply-demand sides, specifically the Arkreen Miner, the Arkren AREC issuance and tokenization protocol, the AREC bridge protocol, the GreenBTC club, and etc. The core features of these applications are all underpinned by on-chain smart contracts.","sidebar":"moreBar"},"token/network-primitives":{"id":"token/network-primitives","title":"Network Primitives","description":"Epochs","sidebar":"economyBar"},"token/token-burn":{"id":"token/token-burn","title":"Token Burn","description":"The Arkreen Foundation adopts a structured AKRE token burn plan to ensure long-term sustainability and maximize the ecosystem\u2019s value. The token burn plan is designed to reduce the total supply of AKRE tokens and align the token\u2019s utility with genuine on-chain green asset growth.","sidebar":"economyBar"},"token/token-distribution":{"id":"token/token-distribution","title":"Token Distribution","description":"Overall Token Distribution","sidebar":"economyBar"},"token/utility-token":{"id":"token/utility-token","title":"Utility Token","description":"AKRE as a Utility Token","sidebar":"economyBar"},"token/what-is-akre":{"id":"token/what-is-akre","title":"What is AKRE?","description":"AKRE (Arkreen Token) is the ERC-20 cryptocurrency and protocol token for the Arkreen Network. Its symbol is AKRE. The token can either be distributed as a reward to contributors who help build and maintain the Arkreen Network, and can also be used to pay Arkreen Network transaction fees and external entity payments for using the green energy data service provided by the Arkreen Network. The maximum supply of AKRE is 10,000,000,000 (10 billion). All AKRE of the Arkreen Network will be distributed to relevant contributors in batches according to the progress of network construction.","sidebar":"economyBar"}}}')}}]);